export interface BlogPost {
  /** URL segment. Must be unique across all posts and lowercase-hyphenated. */
  slug: string;
  /** Post title. */
  title: string;
  /** ISO 8601 date (YYYY-MM-DD). Used for sorting and <time dateTime>. */
  date: string;
  /** Optional summary. Used for metadata and the /blog index card. */
  description?: string;
  /** Optional project tags shown on the index and post page. */
  tags?: string[];
  /** Body content as an array of paragraphs. A paragraph starting with "## " renders as a subheading. */
  content: string[];
}

